/* heat-3d.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "heat-3d.h"


/* Array initialization.
 *
 * Optimization notes:
 * - Use a local pointer to the 3D arrays to avoid repeated VLA
 *   index arithmetic in the inner loops.
 * - Compute the initialization value once per element and store it
 *   into both A and B to keep the original semantics.
 */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		 DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  int i, j, k;

  /* Local views of the 3D arrays.
   * Types:
   *   A_ and B_ are "pointers to [n][n] arrays of DATA_TYPE".
   */
  DATA_TYPE (*A_)[n][n] = A;
  DATA_TYPE (*B_)[n][n] = B;

  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      /* Pointers to the innermost (contiguous) k-dimension rows. */
      DATA_TYPE *Ai = A_[i][j];
      DATA_TYPE *Bi = B_[i][j];

      for (k = 0; k < n; k++) {
        DATA_TYPE value =
          (DATA_TYPE)(i + j + (n - k)) * SCALAR_VAL(10.0) / (DATA_TYPE)n;

        Ai[k] = value;
        Bi[k] = value;
      }
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n))

{
  int i, j, k;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      for (k = 0; k < n; k++) {
         if ((i * n * n + j * n + k) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
         fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j][k]);
      }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimization overview:
 * - Introduce restrict-qualified top-level pointers A_ and B_
 *   so the compiler can assume A and B do not alias and
 *   vectorize more aggressively.
 * - Hoist invariant bounds and constants outside the loops.
 * - Within the i,j loops, take row pointers (Ai, Bi, etc.) once
 *   and reuse them in the k-loop to reduce index arithmetic.
 * - Reuse the central point A[i][j][k]/B[i][j][k] via a scalar
 *   variable and compute 2*center once per lattice point.
 * - Add optional OpenMP parallelism (ignored by compilers that
 *   are not invoked with -fopenmp) over the i,j loops to utilize
 *   many cores. Each (i,j,k) point is written exactly once, so
 *   this is race-free.
 *
 * All algebraic expressions are kept structurally equivalent to
 * the original (up to common subexpression reuse of 2*center),
 * preserving floating-point semantics for each point.
 */
static
void kernel_heat_3d[[gnu::flatten, gnu::noinline]](int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		      DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  int t;

  /* Local restrict-qualified views of the 3D arrays.
   * Types:
   *   A_ and B_ are "pointers to [n][n] arrays of DATA_TYPE".
   * We only access the data through A_ and B_ in this function,
   * so the restrict qualifier is valid and helps alias analysis.
   */
  DATA_TYPE (* restrict A_)[n][n] = A;
  DATA_TYPE (* restrict B_)[n][n] = B;

  /* Effective loop bound (PolyBench may redefine _PB_N). */
  const int n_eff   = _PB_N;
  const int i_start = 1;
  const int i_end   = n_eff - 1;
  const int j_start = 1;
  const int j_end   = n_eff - 1;
  const int k_start = 1;
  const int k_end   = n_eff - 1;

  /* Constants used in the stencil. */
  const DATA_TYPE c   = SCALAR_VAL(0.125);
  const DATA_TYPE two = SCALAR_VAL(2.0);

#pragma scop
  for (t = 1; t <= TSTEPS; t++) {

    /* First sweep: A -> B
     * Each (i,j,k) in the interior is updated independently,
     * so the i,j loops are parallelizable and vectorizable.
     */
#pragma omp parallel for collapse(2) schedule(static) if (n_eff >= 16)
    for (int i = i_start; i < i_end; i++) {
      for (int j = j_start; j < j_end; j++) {

        /* Take row pointers once per (i,j) and reuse them in k-loop.
         * Types:
         *   Ai, Aim1, Aip1 are "pointers to [n] arrays of DATA_TYPE".
         *   Aij, Aijm1, Aijp1, Aim1j, Aip1j are "DATA_TYPE *" and
         *   therefore index only along the innermost (contiguous) k-dim.
         */
        DATA_TYPE (*Ai)  [n] = A_[i];
        DATA_TYPE (*Aim1)[n] = A_[i-1];
        DATA_TYPE (*Aip1)[n] = A_[i+1];

        DATA_TYPE *Aij   = Ai[j];
        DATA_TYPE *Aijm1 = Ai[j-1];
        DATA_TYPE *Aijp1 = Ai[j+1];
        DATA_TYPE *Aim1j = Aim1[j];
        DATA_TYPE *Aip1j = Aip1[j];

        DATA_TYPE *Bij   = B_[i][j];

        for (int k = k_start; k < k_end; k++) {
          const DATA_TYPE center     = Aij[k];
          const DATA_TYPE two_center = two * center;

          /* Expression is structurally identical to the original:
           *   0.125*(A[i+1][j][k] - 2*A[i][j][k] + A[i-1][j][k]) +
           *   0.125*(A[i][j+1][k] - 2*A[i][j][k] + A[i][j-1][k]) +
           *   0.125*(A[i][j][k+1] - 2*A[i][j][k] + A[i][j][k-1]) +
           *   A[i][j][k]
           * but written using preloaded neighbors and two_center.
           */
          Bij[k] =
              c * (Aip1j[k] - two_center + Aim1j[k]) +
              c * (Aijp1[k] - two_center + Aijm1[k]) +
              c * (Aij[k+1] - two_center + Aij[k-1]) +
              center;
        }
      }
    }

    /* Second sweep: B -> A, symmetric to the first sweep. */
#pragma omp parallel for collapse(2) schedule(static) if (n_eff >= 16)
    for (int i = i_start; i < i_end; i++) {
      for (int j = j_start; j < j_end; j++) {

        DATA_TYPE (*Bi)  [n] = B_[i];
        DATA_TYPE (*Bim1)[n] = B_[i-1];
        DATA_TYPE (*Bip1)[n] = B_[i+1];

        DATA_TYPE *Bij   = Bi[j];
        DATA_TYPE *Bijm1 = Bi[j-1];
        DATA_TYPE *Bijp1 = Bi[j+1];
        DATA_TYPE *Bim1j = Bim1[j];
        DATA_TYPE *Bip1j = Bip1[j];

        DATA_TYPE *Aij   = A_[i][j];

        for (int k = k_start; k < k_end; k++) {
          const DATA_TYPE center     = Bij[k];
          const DATA_TYPE two_center = two * center;

          Aij[k] =
              c * (Bip1j[k] - two_center + Bim1j[k]) +
              c * (Bijp1[k] - two_center + Bijm1[k]) +
              c * (Bij[k+1] - two_center + Bij[k-1]) +
              center;
        }
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_3D_ARRAY_DECL(A, DATA_TYPE, N, N, N, n, n, n);
  POLYBENCH_3D_ARRAY_DECL(B, DATA_TYPE, N, N, N, n, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_heat_3d (tsteps, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
