         fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j][k]);
      }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_heat_3d [[gnu::flatten, gnu::noinline]] (int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		      DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  int t, i, j, k;

  /* In PolyBench, '_PB_N' is the effective loop bound (<= N).  We keep
     using it for loop limits to preserve the original behavior. */
  const int n_ = _PB_N;

  /* Create local restrict-qualified aliases.  Function parameters of
     array type decay to pointers to the first element; adding 'restrict'
     here tells the compiler that A and B do not overlap, which enables
     better vectorization and code motion.  We only access the data
     through A_ and B_ below, so the restrict contract is respected. */
  DATA_TYPE (*restrict A_)[N][N] = A;
  DATA_TYPE (*restrict B_)[N][N] = B;

  /* Hoist scalar constants out of the loops to avoid repeated
     SCALAR_VAL conversions and to make the arithmetic clearer. */
  const DATA_TYPE c0_125 = SCALAR_VAL(0.125);
  const DATA_TYPE c2     = SCALAR_VAL(2.0);

  /* Avoid unused-parameter warnings while still matching the original
     semantics (tsteps == TSTEPS, n == N in this benchmark). */
  (void)tsteps;
  (void)n;

#pragma scop
  for (t = 1; t <= TSTEPS; t++) {

    /* Tiling factors for i and j.  These improve cache reuse for the
       3D stencil while keeping the innermost loop on k, which is the
       contiguous dimension in memory (row-major layout).  The values
       are chosen for typical x86-64 L1/L2 caches but work for any n_. */
    const int tile_i = 32;
    const int tile_j = 32;

    /* --------------------------------------------------------------
       Phase 1: update B from A (B = stencil(A))
       -------------------------------------------------------------- */
    for (int ii = 1; ii < n_ - 1; ii += tile_i)
    {
      const int i_max = (ii + tile_i < n_ - 1) ? (ii + tile_i) : (n_ - 1);

      for (int jj = 1; jj < n_ - 1; jj += tile_j)
      {
        const int j_max = (jj + tile_j < n_ - 1) ? (jj + tile_j) : (n_ - 1);

        for (i = ii; i < i_max; ++i)
        {
          for (j = jj; j < j_max; ++j)
          {
            /* For fixed (i,j), cache the k-lines of the current point
               and its 3D neighbors into simple 1D pointers.  This
               reduces the number of address calculations in the
               innermost loop and makes the access pattern very clear
               for the optimizer and vectorizer. */
            DATA_TYPE *restrict a_im1 = &A_[i-1][j][0];
            DATA_TYPE *restrict a_i   = &A_[i  ][j][0];
            DATA_TYPE *restrict a_ip1 = &A_[i+1][j][0];
            DATA_TYPE *restrict a_jm1 = &A_[i][j-1][0];
            DATA_TYPE *restrict a_jp1 = &A_[i][j+1][0];
            DATA_TYPE *restrict b_i   = &B_[i  ][j][0];

            /* Each iteration of the k-loop reads only from A and writes
               to B, so there are no loop-carried dependencies.  The
               'ivdep' pragma tells GCC that it may ignore any assumed
               dependencies and freely vectorize/unroll the loop. */
#pragma GCC ivdep
#pragma GCC unroll 8
            for (k = 1; k < n_ - 1; ++k)
            {
              const DATA_TYPE center = a_i[k];

              const DATA_TYPE lap_i =
                  a_ip1[k] - c2 * center + a_im1[k];
              const DATA_TYPE lap_j =
                  a_jp1[k] - c2 * center + a_jm1[k];
              const DATA_TYPE lap_k =
                  a_i[k+1] - c2 * center + a_i[k-1];

              b_i[k] =  c0_125 * lap_i
                      + c0_125 * lap_j
                      + c0_125 * lap_k
                      + center;
            }
          }
        }
      }
    }

    /* --------------------------------------------------------------
       Phase 2: update A from B (A = stencil(B))
       -------------------------------------------------------------- */
    for (int ii = 1; ii < n_ - 1; ii += tile_i)
    {
      const int i_max = (ii + tile_i < n_ - 1) ? (ii + tile_i) : (n_ - 1);

      for (int jj = 1; jj < n_ - 1; jj += tile_j)
      {
        const int j_max = (jj + tile_j < n_ - 1) ? (jj + tile_j) : (n_ - 1);

        for (i = ii; i < i_max; ++i)
        {
          for (j = jj; j < j_max; ++j)
          {
            DATA_TYPE *restrict b_im1 = &B_[i-1][j][0];
            DATA_TYPE *restrict b_i   = &B_[i  ][j][0];
            DATA_TYPE *restrict b_ip1 = &B_[i+1][j][0];
            DATA_TYPE *restrict b_jm1 = &B_[i][j-1][0];
            DATA_TYPE *restrict b_jp1 = &B_[i][j+1][0];
            DATA_TYPE *restrict a_i   = &A_[i  ][j][0];

#pragma GCC ivdep
#pragma GCC unroll 8
            for (k = 1; k < n_ - 1; ++k)
            {
              const DATA_TYPE center = b_i[k];

              const DATA_TYPE lap_i =
                  b_ip1[k] - c2 * center + b_im1[k];
              const DATA_TYPE lap_j =
                  b_jp1[k] - c2 * center + b_jm1[k];
              const DATA_TYPE lap_k =
                  b_i[k+1] - c2 * center + b_i[k-1];

              a_i[k] =  c0_125 * lap_i
                      + c0_125 * lap_j
                      + c0_125 * lap_k
                      + center;
            }
          }
        }
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
