      for (k = 0; k < n; k++) {
         if ((i * n * n + j * n + k) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
         fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j][k]);
      }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_heat_3d [[gnu::flatten, gnu::noinline]] (int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		      DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  int t, i, j, k;

  /* tsteps is passed in but PolyBench traditionally fixes the number of
     iterations through the TSTEPS macro. Keep original semantics. */
  (void)tsteps;

  /* Use the PolyBench loop bound (normally equal to n). */
  const int n_inner = _PB_N;
  const int n_last  = n_inner - 1;  /* last valid index */
  /* Precompute scalar coefficients once. */
  const DATA_TYPE c0 = SCALAR_VAL(0.125);
  const DATA_TYPE c1 = SCALAR_VAL(2.0);

  /* Simple cache blocking in the i/j dimensions to improve spatial
     locality when N is large. These tile sizes are chosen to be small
     enough for L1/L2 while still giving good loop efficiency. Edge
     tiles are handled explicitly and do not require N to be a multiple
     of the tile size. */
  const int I_BLOCK = 32;
  const int J_BLOCK = 32;

#pragma scop
  for (t = 1; t <= TSTEPS; t++) {

    /* ----------------------------------------------------------------
     * First sweep: update B from A
     * ----------------------------------------------------------------
     * Every update of B[i][j][k] depends only on values from A at the
     * same time step, so all (i,j,k) iterations in this sweep are
     * independent and can be safely reordered or vectorized.
     */
    for (int ii = 1; ii < n_last; ii += I_BLOCK) {
      int i_end = ii + I_BLOCK;
      if (i_end > n_last)
        i_end = n_last;

      for (int jj = 1; jj < n_last; jj += J_BLOCK) {
        int j_end = jj + J_BLOCK;
        if (j_end > n_last)
          j_end = n_last;

        for (i = ii; i < i_end; i++) {
          for (j = jj; j < j_end; j++) {

            /* Pointers to contiguous k-lines for this (i,j) and its
               six neighbors.  Using 1-D pointers reduces address
               arithmetic in the innermost loop and exposes a simple
               stride-1 access pattern for the compiler.  The restrict
               qualifiers are valid because these lines are disjoint
               memory regions. */
            DATA_TYPE       *restrict B_ij     = &B[i][j][0];
            const DATA_TYPE *restrict A_center = &A[i][j][0];
            const DATA_TYPE *restrict A_im1    = &A[i-1][j][0];
            const DATA_TYPE *restrict A_ip1    = &A[i+1][j][0];
            const DATA_TYPE *restrict A_jm1    = &A[i][j-1][0];
            const DATA_TYPE *restrict A_jp1    = &A[i][j+1][0];

            /* No loop-carried dependencies in k: we only read from A
               and write to B, so it is safe to tell the compiler to
               ignore assumed dependencies and vectorize aggressively. */
#pragma GCC ivdep
            for (k = 1; k < n_last; k++) {
              const DATA_TYPE center = A_center[k];

              B_ij[k] =
                  c0 * (A_ip1[k]     - c1 * center + A_im1[k])
                + c0 * (A_jp1[k]     - c1 * center + A_jm1[k])
                + c0 * (A_center[k+1] - c1 * center + A_center[k-1])
                + center;
            }
          }
        }
      }
    }

    /* ----------------------------------------------------------------
     * Second sweep: update A from B
     * ----------------------------------------------------------------
     * Structure is identical to the first sweep, with roles of A and B
     * exchanged.  This symmetry (and code duplication) is intentional:
     * keeping the code explicit helps the compiler optimize each sweep
     * independently and avoids function-call overhead inside the
     * timed region.
     */
    for (int ii = 1; ii < n_last; ii += I_BLOCK) {
      int i_end = ii + I_BLOCK;
      if (i_end > n_last)
        i_end = n_last;

      for (int jj = 1; jj < n_last; jj += J_BLOCK) {
        int j_end = jj + J_BLOCK;
        if (j_end > n_last)
          j_end = n_last;

        for (i = ii; i < i_end; i++) {
          for (j = jj; j < j_end; j++) {

            DATA_TYPE       *restrict A_ij     = &A[i][j][0];
            const DATA_TYPE *restrict B_center = &B[i][j][0];
            const DATA_TYPE *restrict B_im1    = &B[i-1][j][0];
            const DATA_TYPE *restrict B_ip1    = &B[i+1][j][0];
            const DATA_TYPE *restrict B_jm1    = &B[i][j-1][0];
            const DATA_TYPE *restrict B_jp1    = &B[i][j+1][0];

#pragma GCC ivdep
            for (k = 1; k < n_last; k++) {
              const DATA_TYPE center = B_center[k];

              A_ij[k] =
                  c0 * (B_ip1[k]     - c1 * center + B_im1[k])
