/* Optimized single 3D heat stencil step:
 *
 *   dst[i][j][k] =
 *       0.125 * (src[i+1][j][k] - 2*src[i][j][k] + src[i-1][j][k]) +
 *       0.125 * (src[i][j+1][k] - 2*src[i][j][k] + src[i][j-1][k]) +
 *       0.125 * (src[i][j][k+1] - 2*src[i][j][k] + src[i][j][k-1]) +
 *       src[i][j][k];
 *
 * Key optimizations:
 * - Use restrict-qualified pointers to tell the compiler A and B
 *   do not alias, enabling better vectorization.
 * - Use pointer arithmetic along the innermost (k) dimension to
 *   minimize address recalculation inside the hot loop.
 * - Hoist constant coefficients outside the loops.
 * - Reuse 2*center value within the k-loop to avoid recomputing it
 *   three times; this is exact in binary floating point for factor 2.
 *
 * The algebraic structure of the stencil is preserved: we only
 * reorganize how array elements are accessed, not the mathematical
 * expression itself.
 */
static inline
void heat_3d_step(int n,
                  DATA_TYPE (*restrict dst)[n][n],
                  const DATA_TYPE (*restrict src)[n][n])
{
  const int N = _PB_N; /* PolyBench-preprocessed problem size */
  const DATA_TYPE c   = SCALAR_VAL(0.125);
  const DATA_TYPE two = SCALAR_VAL(2.0);

  for (int i = 1; i < N - 1; ++i)
  {
    const DATA_TYPE (*restrict src_im1)[n] = src[i-1];
    const DATA_TYPE (*restrict src_i  )[n] = src[i];
    const DATA_TYPE (*restrict src_ip1)[n] = src[i+1];
    DATA_TYPE       (*restrict dst_i  )[n] = dst[i];

    for (int j = 1; j < N - 1; ++j)
    {
      const DATA_TYPE *restrict src_im1j = src_im1[j];
      const DATA_TYPE *restrict src_ij   = src_i[j];
      const DATA_TYPE *restrict src_ip1j = src_ip1[j];
      const DATA_TYPE *restrict src_ijm1 = src_i[j-1];
      const DATA_TYPE *restrict src_ijp1 = src_i[j+1];
      DATA_TYPE       *restrict dst_ij   = dst_i[j];

      /* Set up rolling pointers along k to avoid repeated
         multi-dimensional index calculations. */
      const DATA_TYPE *restrict center_ptr = &src_ij[1];   /* src[i][j][1]   */
      const DATA_TYPE *restrict xm_ptr     = &src_ij[0];   /* src[i][j][0]   */
      const DATA_TYPE *restrict zm_ptr     = &src_im1j[1]; /* src[i-1][j][1] */
      const DATA_TYPE *restrict zp_ptr     = &src_ip1j[1]; /* src[i+1][j][1] */
      const DATA_TYPE *restrict ym_ptr     = &src_ijm1[1]; /* src[i][j-1][1] */
      const DATA_TYPE *restrict yp_ptr     = &src_ijp1[1]; /* src[i][j+1][1] */
      DATA_TYPE       *restrict dst_ptr    = &dst_ij[1];   /* dst[i][j][1]   */

      /* No loop-carried dependencies along k; enable aggressive
         vectorization if the compiler is conservative. */
#pragma GCC ivdep
      for (int k = 1; k < N - 1; ++k)
      {
        const DATA_TYPE center    = *center_ptr;
        const DATA_TYPE m2_center = two * center; /* exact for factor 2 */

        /* Neighbor differences in each dimension, preserving the
           original structure (value - 2*center + opposite neighbor). */
        const DATA_TYPE tmp_i = *zp_ptr        - m2_center + *zm_ptr;     /* i+1 / i-1 */
        const DATA_TYPE tmp_j = *yp_ptr        - m2_center + *ym_ptr;     /* j+1 / j-1 */
        const DATA_TYPE tmp_k = center_ptr[1]  - m2_center + *xm_ptr;     /* k+1 / k-1 */

        *dst_ptr = c * tmp_i + c * tmp_j + c * tmp_k + center;

        ++center_ptr;
        ++xm_ptr;
        ++zm_ptr;
        ++zp_ptr;
        ++ym_ptr;
        ++yp_ptr;
        ++dst_ptr;
      }
    }
  }
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_heat_3d[[gnu::flatten, gnu::noinline]](int tsteps,
                      int n,
                      DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
                      DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  /* Create restrict-qualified local views of the input arrays to help
     the optimizer. The original array parameters are not used after
     this point. */
  DATA_TYPE (*restrict A_)[n][n] = A;
  DATA_TYPE (*restrict B_)[n][n] = B;

  /* Use PolyBench-preprocessed time-step bound, which may depend on
     the runtime parameter tsteps. */
  const int T = _PB_TSTEPS;

  int t;

#pragma scop
  for (t = 0; t < T; ++t) {
    /* First phase: update B from A */
    heat_3d_step(n, B_, A_);

    /* Second phase: update A from B */
    heat_3d_step(n, A_, B_);
  }
#pragma endscop
}


